      Toast.show({ content: '请选择 JPG、PNG 或 WebP 图片' });
      return;
    }
    if (file.size > 5 * 1024 * 1024) {
      Toast.show({ content: '头像图片不能超过 5MB' });
      return;
    }
    avatarMutation.mutate(file);
  };

